mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g3-1/bot.mjs';
process.env.STATE_DIR = mkdtempSync(path.join(tmpdir(), 'bot-state-'));
const bot = await import(BOT);
const { recordUnsubscribe: unsub, recordResubscribe: resub, mayEmail } = bot;
const T = (s) => new Date(`2026-10-01T${s}Z`);
const NOW = new Date('2026-10-22T12:00:00Z');
const mkt = (to) => ({ to, kind: 'marketing' });
const tx = (to) => ({ to, kind: 'transactional' });

// 1. basic: unsub blocks marketing, not transactional, not others
await unsub('ann@example.com', T('10:00:00'));
assert.deepEqual(await mayEmail(mkt('ann@example.com'), NOW), { allowed: false, reason: 'unsubscribed' });
assert.deepEqual(await mayEmail(tx('ann@example.com'), NOW), { allowed: true, reason: null });
assert.deepEqual(await mayEmail(mkt('bob@example.com'), NOW), { allowed: true, reason: null });

// 2. identity normalization: case, header form, +tag, gmail dots, googlemail
await unsub('  Jane Doe <<EMAIL>>', T('10:00:00'));
assert.equal((await mayEmail(mkt('<EMAIL>'), NOW)).reason, 'unsubscribed');
assert.equal((await mayEmail(mkt('<EMAIL>'), NOW)).reason, 'unsubscribed');
assert.equal((await mayEmail(mkt('<EMAIL>'), NOW)).reason, 'unsubscribed');
assert.equal((await mayEmail(tx('<EMAIL>'), NOW)).allowed, true);

// 3. out-of-order: resub (12:00) arrives before unsub (11:00); latest wins -> allowed
await resub('cy@example.com', T('12:00:00'));
assert.equal((await mayEmail(mkt('cy@example.com'), NOW)).allowed, true);
await unsub('cy@example.com', T('11:00:00'));
assert.equal((await mayEmail(mkt('cy@example.com'), NOW)).allowed, true, 'resub later than late-arriving unsub');

// 4. unsub later than resub -> blocked
await resub('dee@example.com', T('09:00:00'));
await unsub('dee@example.com', T('09:30:00'));
assert.equal((await mayEmail(mkt('dee@example.com'), NOW)).reason, 'unsubscribed');

// 5. tie -> unsubscribe wins
await unsub('eve@example.com', T('10:00:00'));
await resub('eve@example.com', T('10:00:00'));
assert.equal((await mayEmail(mkt('eve@example.com'), NOW)).reason, 'unsubscribed');

// 6. resub stamped after now (clock skew) does not re-enable
await unsub('fay@example.com', T('10:00:00'));
await resub('fay@example.com', T('13:00:00'));
assert.equal((await mayEmail(mkt('fay@example.com'), NOW)).reason, 'unsubscribed');

// 7. resubscribe after unsubscribe, both in the past -> allowed again
await unsub('gus@example.com', T('08:00:00'));
await resub('gus@example.com', T('08:05:00'));
assert.equal((await mayEmail(mkt('gus@example.com'), NOW)).allowed, true);

// 8. idempotent duplicate recording
await unsub('ann@example.com', T('10:00:00'));
await unsub('ann@example.com', T('10:00:00'));
assert.equal((await mayEmail(mkt('ann@example.com'), NOW)).reason, 'unsubscribed');

// 9. invalid input fails closed / throws
assert.equal((await mayEmail(mkt('not-an-address'), NOW)).reason, 'invalid_recipient');
assert.equal((await mayEmail({ to: '<EMAIL>', kind: 'newsletter' }, NOW)).reason, 'unknown_message_kind');
await assert.rejects(unsub('ann@example.com', new Date('nope')), TypeError);
await assert.rejects(unsub('', T('10:00:00')), TypeError);
await assert.rejects(mayEmail(mkt('ann@example.com'), 'now'), TypeError);

// 10. STATE_DIR unset -> throws (gate must not allow)
const saved = process.env.STATE_DIR; delete process.env.STATE_DIR;
await assert.rejects(mayEmail(mkt('zed@example.com'), NOW), /STATE_DIR/);
process.env.STATE_DIR = saved;

console.log('in-process checks passed; STATE_DIR =', saved);
EOF
cd /tmp/bot-check && node check.mjs

